    sse_encode_media_session_ref(self, serializer);
  }

  @protected
  void sse_encode_box_autoadd_media_source(
    MediaSource self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_media_source(self, serializer);
  }

  @protected
  void sse_encode_bridge_response(
    BridgeResponse self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_u_16(self.status, serializer);
    sse_encode_String(self.contentType, serializer);
    sse_encode_list_prim_u_8_strict(self.body, serializer);
  }

  @protected
  void sse_encode_i_64(PlatformInt64 self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putPlatformInt64(self);
  }

  @protected
  void sse_encode_list_prim_u_8_loose(
    List<int> self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_i_32(self.length, serializer);
    serializer.buffer.putUint8List(
      self is Uint8List ? self : Uint8List.fromList(self),
    );
  }

  @protected
  void sse_encode_list_prim_u_8_strict(
    Uint8List self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_i_32(self.length, serializer);
    serializer.buffer.putUint8List(self);
  }

  @protected
  void sse_encode_media_error(MediaError self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.code, serializer);
    sse_encode_String(self.message, serializer);
  }

  @protected
  void sse_encode_media_session(MediaSession self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_media_session_ref(self.session, serializer);
    sse_encode_String(self.playbackUrl, serializer);
    sse_encode_u_64(self.contentLength, serializer);
    sse_encode_String(self.contentType, serializer);
  }

  @protected
  void sse_encode_media_session_ref(
    MediaSessionRef self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.id, serializer);
    sse_encode_u_64(self.generation, serializer);
  }

  @protected
  void sse_encode_media_source(MediaSource self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case MediaSource_RemoteHttps(url: final url):
        sse_encode_i_32(0, serializer);
        sse_encode_String(url, serializer);
      case MediaSource_LocalFile(path: final path):
        sse_encode_i_32(1, serializer);
        sse_encode_String(path, serializer);
    }
  }

